import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { registerUser } from '../api';

function Register({ onLogin }) {
  const [form, setForm] = useState({ name: '', email: '', password: '', role: 'staff' });
  const [errors, setErrors] = useState({});
  const [serverError, setServerError] = useState('');
  const [loading, setLoading] = useState(false);

  // Validate a single field as user types
  const validateField = (name, value) => {
    let error = '';

    if (name === 'name') {
      if (value.trim().length === 0) error = 'Name is required';
      else if (value.trim().length < 2) error = 'Name must be at least 2 characters';
      else if (!/^[a-zA-Z\s.]+$/.test(value)) error = 'Name can only contain letters and spaces';
    }

    if (name === 'email') {
      if (value.trim().length === 0) error = 'Email is required';
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) error = '❌ Invalid email — use format like name@gmail.com';
      else error = ''; // valid
    }

    if (name === 'password') {
      if (value.length === 0) error = 'Password is required';
      else if (value.length < 6) error = `Too short — ${6 - value.length} more characters needed`;
      else if (!/[A-Z]/.test(value)) error = 'Add at least one uppercase letter (A-Z)';
      else if (!/[0-9]/.test(value)) error = 'Add at least one number (0-9)';
    }

    return error;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm({ ...form, [name]: value });

    // Validate as user types
    const error = validateField(name, value);
    setErrors({ ...errors, [name]: error });
  };

  // Check if a field is valid (has value and no error)
  const isValid = (name) => form[name].length > 0 && !errors[name];

  const handleSubmit = async (e) => {
    e.preventDefault();
    setServerError('');

    // Validate all fields before submitting
    const newErrors = {
      name: validateField('name', form.name),
      email: validateField('email', form.email),
      password: validateField('password', form.password),
    };
    setErrors(newErrors);

    // Stop if any errors
    if (Object.values(newErrors).some(err => err !== '')) return;

    setLoading(true);
    try {
      const res = await registerUser(form);
      onLogin(res.data.user, res.data.token);
    } catch (err) {
      setServerError(err.response?.data?.message || 'Registration failed. Try again.');
    } finally {
      setLoading(false);
    }
  };

  const pageStyle = {
    minHeight: '100vh',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    background: 'linear-gradient(135deg, #1e293b, #334155)'
  };

  const cardStyle = {
    background: 'white',
    padding: '2.5rem',
    borderRadius: '16px',
    width: '100%',
    maxWidth: '420px',
    boxShadow: '0 20px 50px rgba(0,0,0,0.3)'
  };

  // Input border turns green when valid, red when error
  const inputStyle = (name) => ({
    width: '100%',
    padding: '0.6rem 0.8rem',
    border: `1.5px solid ${errors[name] ? '#ef4444' : isValid(name) ? '#16a34a' : '#d1d5db'}`,
    borderRadius: '8px',
    fontSize: '1rem',
    outline: 'none',
    transition: 'border 0.2s'
  });

  return (
    <div style={pageStyle}>
      <div style={cardStyle}>
        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
          <div style={{ fontSize: '2.5rem' }}>📝</div>
          <h1 style={{ fontSize: '1.5rem', color: '#1e293b', marginBottom: '0.3rem' }}>
            Create Account
          </h1>
          <p style={{ color: '#64748b', fontSize: '0.9rem' }}>Join Staff Meeting Manager</p>
        </div>

        <form onSubmit={handleSubmit}>

          {/* Full Name */}
          <div className="form-group">
            <label>Full Name</label>
            <input
              type="text"
              name="name"
              placeholder="Dr. John Smith"
              value={form.name}
              onChange={handleChange}
              style={inputStyle('name')}
            />
            {errors.name && (
              <p style={{ color: '#ef4444', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                ❌ {errors.name}
              </p>
            )}
            {isValid('name') && (
              <p style={{ color: '#16a34a', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                ✅ Looks good!
              </p>
            )}
          </div>

          {/* Email */}
          <div className="form-group">
            <label>Email Address</label>
            <input
              type="text"
              name="email"
              placeholder="your@college.edu"
              value={form.email}
              onChange={handleChange}
              style={inputStyle('email')}
            />
            {errors.email && (
              <p style={{ color: '#ef4444', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                {errors.email}
              </p>
            )}
            {isValid('email') && (
              <p style={{ color: '#16a34a', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                ✅ Valid email!
              </p>
            )}
          </div>

          {/* Password */}
          <div className="form-group">
            <label>Password</label>
            <input
              type="password"
              name="password"
              placeholder="Min 6 chars, 1 uppercase, 1 number"
              value={form.password}
              onChange={handleChange}
              style={inputStyle('password')}
            />
            {errors.password && (
              <p style={{ color: '#ef4444', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                ❌ {errors.password}
              </p>
            )}
            {isValid('password') && (
              <p style={{ color: '#16a34a', fontSize: '0.8rem', marginTop: '0.3rem' }}>
                ✅ Strong password!
              </p>
            )}

            {/* Password strength bar */}
            {form.password.length > 0 && (
              <div style={{ marginTop: '0.5rem' }}>
                <div style={{ display: 'flex', gap: '4px' }}>
                  {[1, 2, 3, 4].map(level => {
                    const strength =
                      (form.password.length >= 6 ? 1 : 0) +
                      (/[A-Z]/.test(form.password) ? 1 : 0) +
                      (/[0-9]/.test(form.password) ? 1 : 0) +
                      (/[^A-Za-z0-9]/.test(form.password) ? 1 : 0);
                    const colors = ['#ef4444', '#f97316', '#eab308', '#16a34a'];
                    return (
                      <div key={level} style={{
                        height: '4px',
                        flex: 1,
                        borderRadius: '2px',
                        background: level <= strength ? colors[strength - 1] : '#e5e7eb',
                        transition: 'background 0.3s'
                      }} />
                    );
                  })}
                </div>
                <p style={{ fontSize: '0.75rem', color: '#64748b', marginTop: '0.3rem' }}>
                  {(() => {
                    const s =
                      (form.password.length >= 6 ? 1 : 0) +
                      (/[A-Z]/.test(form.password) ? 1 : 0) +
                      (/[0-9]/.test(form.password) ? 1 : 0) +
                      (/[^A-Za-z0-9]/.test(form.password) ? 1 : 0);
                    return ['Weak', 'Fair', 'Good', 'Strong'][s - 1] || 'Too short';
                  })()}
                </p>
              </div>
            )}
          </div>

          {serverError && (
            <div style={{
              background: '#fee2e2', color: '#991b1b',
              padding: '0.7rem 1rem', borderRadius: '8px',
              fontSize: '0.9rem', marginBottom: '1rem'
            }}>
              ❌ {serverError}
            </div>
          )}

          <button
            type="submit"
            className="btn btn-primary"
            disabled={loading}
            style={{ width: '100%', padding: '0.8rem', marginTop: '0.5rem' }}
          >
            {loading ? 'Creating account...' : 'Create Account'}
          </button>
        </form>

        <p style={{ textAlign: 'center', marginTop: '1.5rem', color: '#64748b', fontSize: '0.9rem' }}>
          Already have an account? <Link to="/login" style={{ color: '#2563eb' }}>Sign in</Link>
        </p>
      </div>
    </div>
  );
}

export default Register;
